+    &:focus,
+    &:hover {
+      color: $navbar-hover-color;
+      background-color: $navbar-bg-color;
+    }
+  }
+
+  .navbar-nav > li > a {
+    color: $navbar-color;
+
+    &:focus,
+    &:hover {
+      color: $navbar-hover-color;
